B.a9h=s(["\uc815\uc2dd\ubd80\ud130 \uccab \uc218\ud655\uae4c\uc9c0 \uba70\uce60 \uac78\ub9ac\ub294\uc9c0\ub294 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694. \uadf8\ub798\uc11c \u201c\ud65c\ucc29\xb7\uc0dd\uc721\u201d \ub2e8\uacc4\ub294 \ub0a0\uc9dc\ub97c \uacc4\uc0b0\ud558\uc9c0 \uc54a\uc544\uc694. \ubcf8\uc78e\uc774 4\uc7a5\uc774 \ub418\uba74 \u2018\uc218\ud655\uae30\u2019\ub85c \uc9c1\uc811 \ub118\uaca8 \uc8fc\uc138\uc694(\uc790\ub8cc: \ubcf8\uc78e 4\uc7a5\ubd80\ud130 \uc218\ud655 \uac00\ub2a5).","\uc2b5\ub3c4 \uae30\uc900\uacfc \uc78e \ud06c\uae30 \uae30\uc900\uc740 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694. \u201c\ucd94\uac00 \ud655\uc778 \ud544\uc694\u201d\ub85c \ud45c\uc2dc\ud574\uc694.","\uaf43\ub208\uc774 \uc0dd\uae30\ub294 \uac83\uc744 \ub9c9\uc73c\ub824\uace0 \ubc24\uc5d0 \uc804\ub4f1\uc744 \ucf1c \uc8fc\ub294 \u201c\uc57c\uac04 \ubcf4\uad11\u201d\uc744 \ud55c\ub2e4\uace0 \uc790\ub8cc\uc5d0 \ub098\uc640 \uc788\uc5b4\uc694(\ubcf8\uc78e 3\uc7a5\ubd80\ud130)."],t.s)
B.Rm=new A.dY("grow","\ud65c\ucc29\xb7\uc0dd\uc721","\ubaa8\uc885\uc774 \ubfcc\ub9ac\ub97c \ub0b4\ub9ac\uace0 \ubcf8\uc78e\uc774 \ub298\uc5b4\ub098\ub294 \ub2e8\uacc4",null,null,B.an,B.p,"\uc815\uc2dd\ubd80\ud130 \ubcf8\uc78e 4\uc7a5\uc774 \ub420 \ub54c\uae4c\uc9c0 \uba70\uce60\uc778\uc9c0\ub294 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694. \ubcf8\uc78e\uc774 4\uc7a5\uc774 \ub418\uba74 \u2018\uc218\ud655\uae30\u2019\ub85c \ub118\uaca8 \uc8fc\uc138\uc694.",!1)
B.Rq=new A.dY("harvest","\uc218\ud655\uae30","\uc544\ub798 \uc78e\ubd80\ud130 \ub530\uba74\uc11c \uacc4\uc18d \ud0a4\uc6b0\ub294 \ub2e8\uacc4",null,null,B.an,B.p,"\ub530\ub73b\ud560 \ub54c\ub294 4~7\uc77c, \uc11c\ub298\ud560 \ub54c\ub294 7~10\uc77c \uac04\uaca9\uc73c\ub85c \uacc4\uc18d \uc218\ud655\ud574\uc694(\uc790\ub8cc). \uc2dc\uc124 \ucd09\uc131\uc7ac\ubc30\ub294 9\uc6d4\ubd80\ud130 \ub2e4\uc74c \ud574 5\uc6d4\uae4c\uc9c0 \uc218\ud655\ud55c\ub2e4\uace0 \ud574\uc694.",!0)
