B.Rt=new A.dY("harvest","\uc218\ud655","\uc6d0\ud558\ub294 \ud06c\uae30\uac00 \ub41c \uc0c8\uc2f9\uc0bc\uc744 \ubf51\uc544 \uc53b\uc5b4 \ub0b4\ub294 \ub2e8\uacc4",null,null,B.an,B.p,"\uc218\ud655 \ud06c\uae30 \uae30\uc900\uacfc \uac78\ub9ac\ub294 \uc77c\uc218\ub294 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694.",!1)
