B.a1F=s(["\uc2e4\ub0b4 \uc21c\ud658\uc2dd \uc218\uacbd(\ub17c\ubb38 \uc870\uac74)\uc73c\ub85c \ud560\uc9c0, \ud558\uc6b0\uc2a4 \ubca0\ub4dc \uc218\uacbd(\ub18d\uac00 \uc0ac\ub840)\uc73c\ub85c \ud560\uc9c0 \uc815\ud574\uc694.","\uc7ac\ubc30 \uae30\uac04 \uc0ac\ub840\ub294 25~30\uc77c, 60\uc77c\uc774 \uc788\uc5b4\uc694. \uc6d0\ud558\ub294 \ud06c\uae30\uc640 \uc6a9\ub3c4\uc5d0 \ub530\ub77c \uc815\ud558\uace0 \uae30\ub85d\ud574\uc694.","\uc790\ub8cc\uac00 \uc801\uc73c\ub2c8 \uc2dc\uc791 \uc804\uc5d0 \ub18d\uc5c5\uae30\uc220\uc13c\ud130\ub098 \ubb18\uc0bc \ud310\ub9e4\ucc98\uc5d0 \uc7ac\ubc30 \ubc29\ubc95\uc744 \ud55c \ubc88 \ub354 \ud655\uc778\ud574\uc694."],t.s)
B.afS=new A.aw("sg-p1",B.aT,null,"\uc7ac\ubc30 \ubc29\uc2dd\uacfc \uc2dc\uc791 \ub0a0\uc9dc \uc815\ud558\uae30",30,B.oV,B.a1F,"\uc7ac\ubc30 \ubc29\uc2dd\uacfc \uc2dc\uc791 \ub0a0\uc9dc, \ubaa9\ud45c \uc7ac\ubc30 \uae30\uac04\uc774 \uc815\ud574\uc84c\uc5b4\uc694.","\uae30\uc900\uc774 \uc560\ub9e4\ud558\uba74 \ucc98\uc74c\uc5d0\ub294 \uc791\uc740 \ubca0\ub4dc \ud558\ub098\ub85c \uc2dc\ud5d8 \uc7ac\ubc30\ub97c \ud574 \ubcf4\uace0 \uae30\ub85d\uc744 \ub0a8\uaca8\uc694.",B.v,B.lj,0,null)
B.a6Y=s(["\ubb18\uc0bc(\uc5b4\ub9b0 \uc778\uc0bc \ubfcc\ub9ac)","\uae68\ub057\ud55c \uc7c1\ubc18","\uc7a5\uac11"],t.s)
B.a13=s(["\ub17c\ubb38\uc5d0\uc11c\ub294 1\ub144\uc0dd \ubb18\uc0bc(\uc885\uc790\uc0bc)\uc744 \uc37c\uc5b4\uc694. \ub0c9\ub3d9 \ubcf4\uad00\ud55c \uac83\uc744 \uc2dc\uc791\uc77c\uc5d0 \uc0ac\uc11c \uc0c1\uc628\uc5d0\uc11c \ub179\uc778 \ub4a4 \ubc14\ub85c \uc62e\uaca8 \uc2ec\uc5c8\uc5b4\uc694.","\ubb18\uc0bc\uc758 \ud06c\uae30\xb7\ub4f1\uae09 \uae30\uc900\uc740 \uc790\ub8cc\uc5d0 \uc5c6\uc5b4\uc694. \ud310\ub9e4\ucc98\uc5d0 \ud06c\uae30\uc640 \ubcf4\uad00 \uc0c1\ud0dc\ub97c \ud655\uc778\ud574\uc694.","\ub179\uc778 \ubb18\uc0bc\uc740 \uc0c1\ud55c \uacf3\uc774 \uc5c6\ub294\uc9c0 \ud558\ub098\uc529 \uc0b4\ud3b4\ubd10\uc694(\uc77c\ubc18 \uc694\ub839)."],t.s)
B.agw=new A.aw("sg-p2",B.aT,null,"\ubb18\uc0bc \uc900\ube44\ud558\uae30",60,B.a6Y,B.a13,"\ubb18\uc0bc\uc774 \ub2e8\ub2e8\ud558\uace0 \uacf0\ud321\uc774\ub098 \ubb34\ub978 \uacf3\uc774 \uc5c6\uc5b4\uc694.","\ubb34\ub974\uac70\ub098 \uacf0\ud321\uc774\uac00 \ud540 \ubb18\uc0bc\uc740 \ubc84\ub824\uc694. \ud310\ub9e4\ucc98\uc5d0 \uc0c1\ud0dc\ub97c \uc54c\ub824\uc694.",B.v,B.aY,0,null)
B.ZI=s(["\ubca0\ub4dc(\ubb3c\uc744 \ub2f4\ub294 \ud1b5)","\uc2a4\ud380\uc9c0 \ubca0\ub4dc","\uc21c\ud658 \ud38c\ud504","LED \uc870\uba85","\ud0c0\uc774\uba38"],t.s)
B.a8B=s(["\ub17c\ubb38 \uc2dc\ud5d8 \ubca0\ub4dc\ub294 \uae38\uc774 500cm, \ud3ed 30cm, \uae4a\uc774 20cm\uc600\uace0, 50\xd730cm \uc2a4\ud380\uc9c0 \ubca0\ub4dc\ub97c \ub744\uc6cc \ubca0\ub4dc\ub9c8\ub2e4 \ubb18\uc0bc 45\uac1c\ub97c \uc62c\ub838\uc5b4\uc694.","\ubb3c\uc744 \uc21c\ud658\uc2dc\ud0a4\ub294 \ud38c\ud504\uc640 LED \uc870\uba85, \ud0c0\uc774\uba38\ub97c \uc810\uac80\ud574\uc694.","\ubca0\ub4dc\uc640 \ud638\uc2a4\ub97c \uae68\ub057\uc774 \uc53b\uc5b4 \ud5f9\uad88\uc694."],t.s)
